#include <rdma/rdma_cma.h>
#include <netinet/in.h>
#include <endian.h>

int is_rdma_ip_valid(__be32 addr) {
    struct rdma_cm_id *id;
    struct sockaddr_in sin;
    int ret;

    id = rdma_create_id(NULL, NULL, 0);
    if (IS_ERR(id))
        return PTR_ERR(id);

    sin.sin_family = AF_INET;
    sin.sin_addr = addr;
    sin.sin_port = 0;

    ret = rdma_bind_addr(id, (struct sockaddr *)&sin);
    if (ret < 0) {
        rdma_destroy_id(id);
        return ret;
    }

    // If the bind succeeded, the address is valid for RDMA
    rdma_destroy_id(id);
    return 0;
}

