#include <rdma/rdma_cma.h>
#include <netinet/in.h>
#include <errno.h>

int check_rdma_address_validity(__be32 addr) {
    struct rdma_cm_id *id;
    struct sockaddr_in sin;
    int ret;

    id = rdma_create_id(NULL, NULL, 0);
    if (!id)
        return -ENOMEM;

    memset(&sin, 0, sizeof(sin));
    sin.sin_family = AF_INET;
    sin.sin_addr = addr;
    sin.sin_port = 0; /* Let the system assign a port */

    ret = rdma_bind_addr(id, (struct sockaddr *)&sin);
    if (ret) {
        rdma_destroy_id(id);
        return ret;
    }

    rdma_destroy_id(id);
    return 0;
}

#include <rdma/rdma_cma.h>
#include <netinet/in.h>

int is_rdma_valid_ip(__be32 addr) {
    struct rdma_id *id;
    struct sockaddr_in addr_in;
    int ret = 0;

    id = rdma_create_id(NULL, NULL, RDMA_PS_TCP, IB_QPT_RC);
    if (IS_ERR(id))
        return PTR_ERR(id);

    memset(&addr_in, 0, sizeof(addr_in));
    addr_in.sin_family = AF_INET;
    addr_in.sin_addr = addr;
    addr_in.sin_port = htons(0); /* Any available port */

    ret = rdma_bind_addr(id, (struct sockaddr *)&addr_in);
    if (ret) {
        rdma_destroy_id(id);
        return ret;
    }

    /* Check if the device is not an InfiniBand device */
    if (!rdma_is_ib_device(id->device)) {
        rdma_destroy_id(id);
        return -EINVAL;
    }

    rdma_destroy_id(id);
    return ret;
}

#include <rdma/rdma_cm.h>
#include <netinet/in.h>

int is_rdma_address_valid(__be32 addr) {
    struct rdma_cm_id *id;
    struct sockaddr_in sin;
    int ret;

    id = rdma_create_id(NULL, NULL, 0);
    if (IS_ERR(id))
        return PTR_ERR(id);

    memset(&sin, 0, sizeof(sin));
    sin.sin_family = AF_INET;
    sin.sin_addr = addr;
    sin.sin_port = htons(0); /* Let the system assign a port */

    ret = rdma_bind_addr(id, (struct sockaddr *)&sin);
    if (ret) {
        rdma_destroy_id(id);
        return ret;
    }

    /* Check if the device is InfiniBand */
    if (!id->device || id->device->rdma_dev_addr.hca_be16[0] != htons(0xffff)) {
        rdma_destroy_id(id);
        return -EINVAL;
    }

    rdma_destroy_id(id);
    return 0;
}
